#!/usr/bin/env python3
"""
Monorepo Changelog & Version Manager

Generates changelogs and updates version numbers based on Git history.
"""

import os
import re
import subprocess
from collections import defaultdict
from datetime import datetime


def run_git_command(cmd):
    """Run a git command and return output."""
    result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
    return result.stdout.strip()


def get_last_tag():
    """Get the last git tag."""
    tags = run_git_command("git tag --sort=-creatordate")
    if tags:
        return tags.split()[0]
    return None


def get_commits_since_tag(tag):
    """Get commit messages from tag to HEAD."""
    if tag is None:
        # Get all commits
        result = run_git_command("git log --oneline HEAD")
    else:
        result = run_git_command(f"git log --oneline {tag}..HEAD")
    return [line for line in result.split('\n') if line] if result else []


def parse_commit_message(line):
    """
    Parse a commit message line.
    Format: type(scope): description
    Returns: (type, scope, description) or (None, None, None)
    """
    pattern = r'^(feat|fix)\(([^)]+)\): (.*)$'
    match = re.match(pattern, line)
    if match:
        return match.group(1), match.group(2), match.group(3)
    return None, None, None


def get_modified_files_for_commit(commit_hash):
    """Get list of files modified in a commit."""
    result = subprocess.run(
        f"git show --name-only --pretty=format: {commit_hash}",
        shell=True,
        capture_output=True,
        text=True
    )
    files = result.stdout.strip().split('\n') if result.stdout.strip() else []
    return files


def get_package_from_file(filepath):
    """Extract package name from a file path like packages/pkg-name/file.txt"""
    if filepath.startswith("packages/"):
        return filepath.split('/')[1]
    return None


def get_all_packages():
    """Get list of all packages from packages/ directory."""
    packages = []
    if os.path.exists("packages"):
        for name in os.listdir("packages"):
            pkg_path = os.path.join("packages", name)
            if os.path.isdir(pkg_path):
                packages.append(name)
    return sorted(packages)


def get_package_deps(pkg_name):
    """
    Get dependencies for a package from packages/<name>/deps.txt.
    Returns list of package names that pkg_name depends on.
    """
    deps_file = os.path.join("packages", pkg_name, "deps.txt")
    if os.path.exists(deps_file):
        with open(deps_file, 'r') as f:
            deps = [line.strip() for line in f if line.strip()]
        return deps
    return []


def get_version_file_path(pkg_name):
    """Get path to VERSION file for a package."""
    return os.path.join("packages", pkg_name, "VERSION")


def get_changelog_file_path(pkg_name):
    """Get path to CHANGELOG.md file for a package."""
    return os.path.join("packages", pkg_name, "CHANGELOG.md")


def parse_version(version_str):
    """Parse version string like '1.0.0' into tuple (major, minor, patch)."""
    parts = version_str.split('.')
    return tuple(int(p) for p in parts)


def format_version(version_tuple):
    """Format version tuple back to string."""
    return '.'.join(str(p) for p in version_tuple)


def bump_version(version_str, bump_type):
    """
    Bump version based on type.
    MAJOR: major++
    MINOR: minor++, patch=0
    PATCH: patch++
    """
    major, minor, patch = parse_version(version_str)

    if bump_type == 'MAJOR':
        return (major + 1, 0, 0)
    elif bump_type == 'MINOR':
        return (major, minor + 1, 0)
    elif bump_type == 'PATCH':
        return (major, minor, patch + 1)
    return (major, minor, patch)


def main():
    # Check if we're in a git repo
    if not run_git_command("git rev-parse --git-dir"):
        print("Error: Not a git repository")
        return

    # Get last tag
    last_tag = get_last_tag()
    print(f"Last tag: {last_tag}")

    # Get commits from tag to HEAD
    commit_lines = get_commits_since_tag(last_tag)
    print(f"Found {len(commit_lines)} commits")

    # Get all packages
    packages = get_all_packages()
    print(f"Packages: {packages}")

    # Data structures
    # commits_by_pkg: {pkg_name: [(type, scope, description), ...]}
    commits_by_pkg = defaultdict(list)

    # Direct bumps from commits: {pkg_name: bump_type}
    direct_bumps = defaultdict(lambda: None)

    # Parse each commit and map to packages
    for line in commit_lines:
        commit_type, scope, description = parse_commit_message(line)
        if commit_type is None:
            continue

        commit_hash = line.split()[0] if line.split() else None
        if not commit_hash:
            continue

        # Get files modified in this commit
        files = get_modified_files_for_commit(commit_hash)

        # Find which packages are affected
        affected_packages = set()
        for f in files:
            pkg = get_package_from_file(f)
            if pkg:
                affected_packages.add(pkg)

        # Determine bump type from commit message
        bump = None
        if "BREAKING CHANGE" in description:
            bump = 'MAJOR'
        elif commit_type == 'feat':
            bump = 'MINOR'
        elif commit_type == 'fix':
            bump = 'PATCH'

        # Record commit and bump
        for pkg in affected_packages:
            commits_by_pkg[pkg].append((commit_type, scope, description))
            if bump is not None:
                # Take highest bump for this package
                current = direct_bumps[pkg]
                if current is None:
                    direct_bumps[pkg] = bump
                else:
                    order = {'MAJOR': 3, 'MINOR': 2, 'PATCH': 1}
                    if order.get(bump, 0) > order.get(current, 0):
                        direct_bumps[pkg] = bump

    print(f"Commits by package: {dict(commits_by_pkg)}")
    print(f"Direct bumps: {dict(direct_bumps)}")

    # Build reverse dependency map: {dep: [packages that depend on it]}
    # If pkg-A is in pkg-B's deps.txt, then pkg-B depends on pkg-A
    # So if pkg-A is bumped, pkg-B must also be bumped
    dependents_of = defaultdict(list)
    for pkg in packages:
        deps = get_package_deps(pkg)
        for dep in deps:
            dependents_of[dep].append(pkg)

    print(f"Dependency graph (dep -> dependents): {dict(dependents_of)}")

    # Propagate dependency bumps
    # Start with direct_bumps
    final_bumps = dict(direct_bumps)

    # Track bump source: 'direct' or 'dep' or None
    bump_source = {}
    for pkg in packages:
        if direct_bumps[pkg] is not None:
            bump_source[pkg] = 'direct'
        else:
            bump_source[pkg] = None

    # Iteratively propagate
    for _ in range(len(packages) + 1):
        changed = False
        for pkg in packages:
            # If this package has no direct bump, check if any of its dependencies are bumped
            # pkg depends on packages listed in pkg's deps.txt
            pkg_deps = get_package_deps(pkg)
            for dep in pkg_deps:
                if final_bumps.get(dep) is not None:
                    # dep is bumped, so pkg needs to be bumped with PATCH
                    if final_bumps[pkg] is None:
                        final_bumps[pkg] = 'PATCH'
                        bump_source[pkg] = 'dep'
                        changed = True
                    # If pkg already has a bump, keep the higher one (already set)

        if not changed:
            break

    print(f"Final bumps: {dict(final_bumps)}")
    print(f"Bump sources: {dict(bump_source)}")

    # Identify packages bumped only due to dependencies
    dep_only_packages = set()
    for pkg in packages:
        if final_bumps[pkg] is not None and bump_source[pkg] == 'dep':
            dep_only_packages.add(pkg)

    print(f"Dependency-only bumped packages: {dep_only_packages}")

    # Process each package and generate outputs
    for pkg in packages:
        if final_bumps[pkg] is None:
            print(f"No bump for {pkg}")
            continue

        new_version = format_version(bump_version("1.0.0", final_bumps[pkg]))
        print(f"{pkg}: bump={final_bumps[pkg]}, new_version={new_version}")

        # Update VERSION file
        version_file = get_version_file_path(pkg)
        with open(version_file, 'w') as f:
            f.write(new_version)
        print(f"  Updated {version_file}")

        # Collect commit descriptions for this package
        pkg_commits = commits_by_pkg.get(pkg, [])

        # Separate features and fixes
        features = []
        fixes = []
        for ct, scope, desc in pkg_commits:
            if ct == 'feat':
                features.append(f"[feat] {desc}")
            elif ct == 'fix':
                fixes.append(f"[fix] {desc}")

        # Build CHANGELOG.md content
        today = datetime.now().strftime("%Y-%m-%d")
        lines = [f"## {new_version} ({today})"]

        if features:
            lines.append("### Features")
            lines.extend(features)

        if fixes:
            lines.append("### Bug Fixes")
            lines.extend(fixes)

        # If bumped only due to dependencies, add Dependencies section
        if pkg in dep_only_packages:
            lines.append("### Dependencies")
            lines.append("- update dependencies")

        changelog_content = '\n'.join(lines) + '\n'

        # Write/update CHANGELOG.md
        changelog_file = get_changelog_file_path(pkg)
        if os.path.exists(changelog_file):
            # Append to existing changelog
            with open(changelog_file, 'a') as f:
                f.write(changelog_content)
        else:
            with open(changelog_file, 'w') as f:
                f.write(changelog_content)

        print(f"  Updated {changelog_file}")

    # Generate root release-notes.md
    with open('release-notes.md', 'w') as f:
        f.write("# Release Notes\n\n")
        for pkg in packages:
            if final_bumps[pkg] is not None:
                new_version = format_version(bump_version("1.0.0", final_bumps[pkg]))
                pkg_commits = commits_by_pkg.get(pkg, [])

                features = []
                fixes = []
                deps_entry = False
                for ct, scope, desc in pkg_commits:
                    if ct == 'feat':
                        features.append(f"- [feat] {desc}")
                    elif ct == 'fix':
                        fixes.append(f"- [fix] {desc}")

                # Check if this package is dep-only
                if pkg in dep_only_packages:
                    deps_entry = True

                f.write(f"## {pkg}\n")
                for feat in features:
                    f.write(feat + "\n")
                for fix in fixes:
                    f.write(fix + "\n")
                if deps_entry:
                    f.write("- [deps] update dependencies\n")
                f.write("\n")

    print("\nGenerated release-notes.md")
    print("Done!")


if __name__ == "__main__":
    main()
