                if pkg not in direct_bumps:
                    direct_bumps[pkg] = bump
                else:
                    order = {'MAJOR': 3, 'MINOR': 2, 'PATCH': 1}
                    if order.get(bump, 0) > order.get(direct_bumps[pkg], 0):
                        direct_bumps[pkg] = bump

