    # Build dependency map: dep -> list of packages that depend on it
    # If pkg-A is in pkg-B's deps.txt, then pkg-B depends on pkg-A
    dependents_of = defaultdict(list)
    for pkg in packages:
        deps = get_package_deps(pkg)
        for dep in deps:
            dependents_of[dep].append(pkg)

    print(f"Dependency graph: {dict(dependents_of)}")

    # Initialize final_bumps for all packages (None means no bump yet)
    final_bumps = {pkg: None for pkg in packages}

    # Set direct bumps
